export class StoryInputError extends Error{}
export function normalize(value){return String(value).normalize('NFKC').replace(/[\u0610-\u061a\u064b-\u065f\u0670\u06d6-\u06ed\u0640]/g,'').replace(/[أإآٱ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632)).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).toLowerCase().replace(/\s+/g,' ').trim()}
export function parsePrompt(value){const raw=String(value).trim();let n=normalize(raw);if(!n||raw.length>600)throw new StoryInputError('اكتب طلبًا قصيرًا لا يتجاوز ٦٠٠ حرف.');
 const noah=/(?:نوح|noah|\bnuh\b|طوفان)/u.test(n),plant=/(?:نبات|نبته|بذر|بذره|بذور|شجر|انبات|\bplants?\b|\bseeds?\b|\btrees?\b)/u.test(n);
 if(noah&&plant)throw new StoryInputError('اختر موضوعًا واحدًا في كل قصة: طوفان نوح أو نمو شجرة من بذرة.');
 if(!noah&&!plant)throw new StoryInputError('هذا الموضوع غير مغطى بعد. المتاح الآن: طوفان نوح، ونمو شجرة من بذرة. لن أؤلف قصة دينية أو علمية خارج هذه المكتبة.');
 if(/(?:بدون|لا اريد|مش عايز|ليس|لا|not|without)\s+(?:قصه\s+)?(?:نوح|noah|طوفان|شجر|بذر|نبات)/u.test(n)||noah&&/(?:موسي|ابراهيم|يوسف|يونس|عيسي|محمد|سليمان|داود|ايوب|اسماعيل|اسحاق|يعقوب|ادريس|زكريا|يحيي|هارون|لوط|moses|abraham|jonah|jesus)/u.test(n))throw new StoryInputError('حدد موضوعًا واحدًا مباشرة. القصص الدينية الأخرى أو الطلبات المنفية غير مغطاة في هذه النسخة.');
 if(/\d+[.,٫]\d+\s*(?:مشاهد|مراحل|لقطات|scenes?|stages?|ثانيه|ثواني|ثوان|seconds?|secs?|دقيقه|دقايق|دقائق|minutes?)/u.test(n))throw new StoryInputError('اكتب عدد المشاهد والمدة بأرقام صحيحة دون كسور.');
 if(/\d+\s*(?:او|الي|or|to|[-–]|و)\s*\d+\s*(?:مشاهد|مراحل|لقطات|scenes?|stages?|ثانيه|ثواني|seconds?|دقيقه|دقائق|minutes?)/u.test(n)||/(?:ساعه|ساعات|hours?\b)/u.test(n))throw new StoryInputError('حدد عددًا واحدًا للمشاهد ومدة واحدة بالثواني أو الدقائق.');
 const words={'ثلاثه':'3','ثلاث':'3','تلاته':'3','اربعه':'4','اربع':'4','خمسه':'5','خمس':'5','three':'3','four':'4','five':'5'};for(const [word,digit]of Object.entries(words))n=n.replace(new RegExp(word+'(?=\\s*(?:مشاهد|مراحل|لقطات|scenes?|stages?))','gu'),digit);
 const counts=[...n.matchAll(/(\d+)\s*(?:مشاهد|مراحل|لقطات|scenes?\b|stages?\b)/gu)].map(m=>Number(m[1]));if(new Set(counts).size>1)throw new StoryInputError('ورد أكثر من عدد للمشاهد. اكتب عددًا واحدًا.');const count=counts[0]??5;if(!counts.length&&/(?:مشاهد|مراحل|لقطات|scenes?\b|stages?\b)/u.test(n))throw new StoryInputError('اكتب عدد المشاهد بالأرقام، مثل ٤ مشاهد.');
 if(count<3||count>5)throw new StoryInputError('النسخة التجريبية تدعم ٣ إلى ٥ مشاهد. اكتب العدد ضمن الطلب.');
 const durations=[];let remainder=n.replace(/(?:دقيقه ونصف|minute and a half)/gu,()=>{durations.push(90);return ' '}).replace(/(?:نصف دقيقه|half a minute)/gu,()=>{durations.push(30);return ' '}).replace(/(?:ربع دقيقه|quarter (?:of )?a minute)/gu,()=>{durations.push(15);return ' '}).replace(/(?:دقيقتين|دقيقتان)/gu,()=>{durations.push(120);return ' '});
 remainder=remainder.replace(/(\d+)\s*(?:ثانيه|ثواني|ثوان|seconds?\b|secs?\b)/gu,(_,v)=>{durations.push(Number(v));return ' '}).replace(/(\d+)\s*(?:دقيقه|دقائق|دقايق|minutes?\b)/gu,(_,v)=>{durations.push(Number(v)*60);return ' '});
 if(/(?:نصف|نص|ربع|ثلث|half|quarter)/u.test(remainder))throw new StoryInputError('اكتب المدة بالأرقام لتجنب التباس الكسور.');
 if(/(?:ثانيه|ثواني|ثوان|seconds?\b|secs?\b|دقائق|دقايق)/u.test(remainder))throw new StoryInputError('اكتب المدة بالأرقام، مثل ٣٠ ثانية أو ٢ دقيقة.');
 if(/(?:دقيقه|minutes?\b)/u.test(remainder)){if(/(?:خلال|لمده|في|for|in)\s+(?:دقيقه|a minute)|^دقيقه|دقيقه$|\ba minute\b/u.test(remainder))durations.push(60);else throw new StoryInputError('اكتب المدة بالأرقام، مثل ٦٠ ثانية.');}
 if(durations.length>1)throw new StoryInputError('اكتب مدة إجمالية واحدة، ولا تجمع أو تقارن بين مدتين.');
 const seconds=durations[0]??(noah?35:30);if(seconds<15||seconds>120||seconds/count<3)throw new StoryInputError('اختر مدة إجمالية من ١٥ إلى ١٢٠ ثانية، وبمتوسط ٣ ثوانٍ على الأقل لكل مشهد.');
 const audience=/(?:اطفال|للصغار|طفل|kids?\b|children\b)/u.test(n)?'children':'general';return {topic:noah?'noah':'plant',count,seconds,audience,prompt:raw};}

const noahTexts=[['بناء السفينة','ألواح وأدوات بناء، تمهيدًا للنجاة','تُبنى السفينة استعدادًا للنجاة.'],['بداية الطوفان','المطر يشتد، والماء يتفجر من الأرض','يهطل المطر، وتتفجر عيون الماء.'],['الصعود إلى السفينة','أزواج من الحيوان تصعد مع بدء الطوفان','تصعد أزواج من الحيوان إلى السفينة.'],['اشتداد الطوفان','السفينة تجري وسط أمواج هائلة','تجري السفينة وسط أمواج كبيرة.'],['انحسار الماء','تتوقف الأمطار وتستقر السفينة على الجودي','ينحسر الماء، وتستقر السفينة على الجودي.']];
const plantTexts=[['بذرة في التربة','تبدأ الحكاية ببذرة صغيرة في تربة مناسبة','نبدأ ببذرة صغيرة في التربة.'],['بداية الإنبات','مع الرطوبة والظروف المناسبة يبدأ الجذر في النمو','ينمو جذر صغير من البذرة.'],['جذور وأوراق','تمتد الجذور وتظهر الساق والأوراق','تمتد الجذور وتظهر أوراق خضراء.'],['شجرة فتية','تواصل الساق والأغصان نموها مع الرعاية','تكبر الشجرة يومًا بعد يوم.'],['شجرة نامية','نمو توضيحي لشجرة، وليس مدة ثابتة لكل النباتات','بالماء والضوء والرعاية تنمو الشجرة.']];
export function planStory(options){const list=options.topic==='noah'?noahTexts:plantTexts,indices=options.count===3?(options.topic==='noah'?[0,3,4]:[0,2,4]):options.count===4?[0,2,3,4]:[0,1,2,3,4];const stages=indices.map((source,index)=>({source,title:list[source][0],caption:list[source][options.audience==='children'?2:1],duration:options.seconds/options.count,index}));
 if(options.topic==='noah'&&options.count<5){stages[0].caption=options.count===3?'تُبنى السفينة، ثم تُحمل فيها أزواج من الحيوان.':stages[0].caption;if(options.count===4){stages[1].title='بدء الطوفان والصعود';stages[1].caption='يبدأ الطوفان وتصعد أزواج من الحيوان إلى السفينة.'}}
 return {...options,title:options.topic==='noah'?'مراحل طوفان نوح':'من بذرة إلى شجرة',stages,notes:options.topic==='noah'?['هذا القالب يغطي مراحل الطوفان، وليس قصة نوح كاملة.','بداية الطوفان والصعود متداخلان في السرد؛ اللوحات للتوضيح.','لا تجسيد للأنبياء أو الأشخاص. شكل السفينة وأنواع الحيوان توضيحية.']:['تمثيل مبسط لنمو شجرة من بذرة؛ ليست كل النباتات أشجارًا.','متطلبات الإنبات ومعدل النمو يختلفان باختلاف النوع والظروف.'],sources:options.topic==='noah'?[{label:'هود ٤٠ إلى ٤٤',url:'https://quran.com/hud/40-44'},{label:'القمر ١١ و١٢',url:'https://quran.com/54/11-12'}]:[{label:'University of Minnesota Extension',url:'https://extension.umn.edu/garden-and-home/yard-and-garden/gardening-in-minnesota/starting-seeds-indoors'}]};}
export function captionLayers(stage){const digits=String(stage.index+1).replace(/\d/g,c=>'٠١٢٣٤٥٦٧٨٩'[Number(c)]);return [{id:'caption',label:'عنوان المرحلة',kind:'text',text:digits+'. '+stage.title,y:126,size:112,maxWidth:1050,color:'#17633e',weight:1.4},{id:'explanation',label:'شرح المرحلة',kind:'text',text:stage.caption,y:195,size:43,maxWidth:1110,color:'#5b6249',weight:1.1}]}
export async function composeStory(plan){const pack=plan.topic==='noah'?await import('./packs/noah-art.mjs'):await import('./packs/plant-art.mjs');const all=plan.topic==='noah'?pack.stages({}):await pack.stages();return plan.stages.map(stage=>{const art=all[stage.source],captions=captionLayers(stage),layers=art.groups.filter(g=>g.body).map(g=>({...g,kind:'svg',weight:/ark|tree|roots/.test(g.id)?2.5:1}));layers.unshift(captions[0]);layers.splice(2,0,captions[1]);if(plan.topic==='noah'&&stage.source===4)layers.push({id:'judi-label',label:'اسم الجبل',kind:'text',text:'الجودي',y:642,size:41,maxWidth:180,color:'#17633e',weight:.7});return {id:art.id,title:stage.title,duration:stage.duration,defs:art.defs.join(''),layers}})}
